// SigTune-Auto - autotuner search demo (hill climbing)
function perf(flags) { var s = 0; for (var i = 0; i < flags.length; i++) s += flags.charCodeAt(i) * (i + 1); return 100000 - (s % 5000); }
var flags = ["-O2", "-O3 -funroll-loops", "-Os", "-O3 -march=native"];
var best = flags.map(function(f) { return { f: f, score: perf(f) }; }).sort(function(a, b) { return b.score - a.score; })[0];
console.log("Tuner: SigTune | Method: CI search");
flags.forEach(function(f) { console.log("  " + f + " -> " + perf(f)); });
console.log("Best: " + best.f + " (" + best.score + ") -> TUNED");

